#!/usr/bin/env node
// Playwright smoke test for every public route. Run AFTER `npm run build`:
//   npm run smoke
// It starts `vite preview` on 127.0.0.1:8081, checks each route at phone and
// desktop widths with the OS colour scheme set to dark AND light, saves
// scrolled full-page screenshots to smoke-output/, and exits 1 on any failure.
//
// Paste the full console output into DECISION_LOG.md. Do not summarise it.
// Do NOT edit this file to make a failure go away; fix the code or ask Chanakya.
//
// Browser: uses Playwright's Chromium. If it is missing run
//   npx playwright install chromium
// or point PLAYWRIGHT_CHROMIUM_PATH at an existing Chromium/Chrome binary.

import { spawn } from "node:child_process";
import { mkdirSync, readFileSync, existsSync } from "node:fs";
import { chromium } from "playwright";

const BASE = "http://127.0.0.1:8081";
const OUT = new URL("../smoke-output/", import.meta.url).pathname;

// Routes that must render. Add new public routes here when they are created.
const ROUTES = [
  { path: "/", expectPath: "/" },
  { path: "/book", expectPath: "/book" },
  { path: "/method", expectPath: "/" }, // redirects to /#how-we-work
  { path: "/admin/login", expectPath: "/admin/login" },
];
const VIEWPORTS = [
  { width: 390, height: 844 },
  { width: 1440, height: 900 },
];
const SCHEMES = ["dark", "light"];
const PAPER = "rgb(248, 247, 244)";

const L = (c) => {
  const v = c.match(/[\d.]+/g).slice(0, 3).map(Number).map((x) => x / 255)
    .map((x) => (x <= 0.03928 ? x / 12.92 : ((x + 0.055) / 1.055) ** 2.4));
  return 0.2126 * v[0] + 0.7152 * v[1] + 0.0722 * v[2];
};
const contrast = (a, b) => { const x = L(a), y = L(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };

async function waitForServer(ms = 30000) {
  const end = Date.now() + ms;
  while (Date.now() < end) {
    try { const r = await fetch(BASE + "/"); if (r.ok) return; } catch { /* not up yet */ }
    await new Promise((r) => setTimeout(r, 500));
  }
  throw new Error("vite preview did not start on " + BASE + " (did you run `npm run build`?)");
}

// `vite preview` does not send the headers Vercel will send. Read them from the
// build output (.vercel/output/config.json, generated from routeRules in
// vite.config.ts) and apply them in the browser, so CSP problems show up here.
function vercelHeaders() {
  const p = new URL("../.vercel/output/config.json", import.meta.url).pathname;
  if (!existsSync(p)) return {};
  const routes = JSON.parse(readFileSync(p, "utf8")).routes || [];
  const all = routes.find((r) => r.src === "/(.*)" && r.headers);
  return all ? all.headers : {};
}
const HEADERS = vercelHeaders();
const CSP = HEADERS["Content-Security-Policy"];
console.log(CSP ? `Applying CSP from build output: ${CSP}\n` : "No CSP found in .vercel/output/config.json (security headers not configured yet)\n");

// Refuse to run against a server that is already on the port: it would be
// serving an old build, and the results would be about the wrong code.
try {
  await fetch(BASE + "/");
  console.log(`SMOKE FAILED: something is already listening on ${BASE}. Stop it (e.g. \`npx kill-port 8081\` or close the old preview) and re-run.`);
  process.exit(1);
} catch { /* port is free, good */ }

mkdirSync(OUT, { recursive: true });
const server = spawn("npx", ["vite", "preview", "--port", "8081", "--host", "127.0.0.1"], { stdio: "ignore" });
let failed = 0;
const fail = (msg) => { failed++; console.log("  ✗ " + msg); };

try {
  await waitForServer();
  const browser = await chromium.launch(
    process.env.PLAYWRIGHT_CHROMIUM_PATH ? { executablePath: process.env.PLAYWRIGHT_CHROMIUM_PATH } : {},
  );

  for (const scheme of SCHEMES) {
    for (const vp of VIEWPORTS) {
      const ctx = await browser.newContext({ viewport: vp, colorScheme: scheme });
      if (Object.keys(HEADERS).length) {
        await ctx.route(BASE + "/**", async (route) => {
          const response = await route.fetch({ maxRedirects: 0 });
          await route.fulfill({ response, headers: { ...response.headers(), ...HEADERS } });
        });
      }
      for (const route of ROUTES) {
        const page = await ctx.newPage();
        const errors = [];
        page.on("pageerror", (e) => errors.push("pageerror: " + e.message));
        page.on("console", (m) => { if (m.type() === "error") errors.push("console: " + m.text()); });
        await page.addInitScript(() => {
          window.__csp = [];
          document.addEventListener("securitypolicyviolation", (e) => window.__csp.push(e.violatedDirective + " " + e.blockedURI));
        });

        const label = `${scheme} ${vp.width}px ${route.path}`;
        console.log(label);
        const res = await page.goto(BASE + route.path, { waitUntil: "networkidle" });
        if (!res || res.status() >= 400) fail(`HTTP ${res ? res.status() : "no response"}`);

        // Scroll through so scroll-reveal sections render before checks/screenshot.
        const height = await page.evaluate(() => document.body.scrollHeight);
        for (let y = 0; y < height; y += 400) { await page.evaluate((v) => window.scrollTo({ top: v, behavior: "instant" }), y); await page.waitForTimeout(80); }
        await page.waitForTimeout(600);

        const r = await page.evaluate(() => {
          const body = getComputedStyle(document.body);
          const anchors = [...document.querySelectorAll('a[href^="#"]')].map((a) => a.getAttribute("href")).filter((h) => h.length > 1);
          return {
            pathname: location.pathname,
            bg: body.backgroundColor,
            ink: body.color,
            htmlClass: document.documentElement.className,
            h1Count: document.querySelectorAll("h1").length,
            title: document.title,
            missingAnchors: [...new Set(anchors)].filter((h) => !document.getElementById(h.slice(1))),
            invisibleSections: [...document.querySelectorAll("main section")].filter((s) => getComputedStyle(s).opacity === "0").map((s) => s.id || s.className.slice(0, 40)),
            csp: window.__csp,
          };
        });

        if (r.pathname !== route.expectPath) fail(`ended on ${r.pathname}, expected ${route.expectPath}`);
        if (r.bg !== PAPER) fail(`body background ${r.bg}, expected ${PAPER}`);
        if (/\bdark\b/.test(r.htmlClass)) fail(`<html> has class "dark"`);
        if (r.h1Count !== 1) fail(`${r.h1Count} <h1> elements, expected exactly 1`);
        if (!r.title) fail("empty <title>");
        if (contrast(r.ink, r.bg) < 4.5) fail(`body text contrast ${contrast(r.ink, r.bg).toFixed(2)} < 4.5`);
        if (r.missingAnchors.length) fail(`in-page links with no target: ${r.missingAnchors.join(", ")}`);
        if (r.invisibleSections.length) fail(`sections still opacity 0 after scrolling: ${r.invisibleSections.join(", ")}`);
        if (r.csp.length) fail(`CSP violations: ${r.csp.join(" | ")}`);
        for (const e of errors) fail(e);

        const name = `${route.path === "/" ? "home" : route.path.slice(1).replace(/\//g, "-")}-${vp.width}-${scheme}.png`;
        await page.screenshot({ path: OUT + name, fullPage: true });
        console.log(`  title="${r.title}" bg=${r.bg} contrast=${contrast(r.ink, r.bg).toFixed(2)} screenshot=smoke-output/${name}`);
        await page.close();
      }
      await ctx.close();
    }
  }
  await browser.close();
} catch (e) {
  fail(e.message);
} finally {
  server.kill();
}

const total = SCHEMES.length * VIEWPORTS.length * ROUTES.length;
console.log(failed ? `\nSMOKE FAILED: ${failed} problem(s) across ${total} page loads` : `\nSMOKE PASSED: ${total}/${total} page loads`);
process.exit(failed ? 1 : 0);
